using System;using UnityEngine;using UnityEngine.Rendering;using LighFight.Runtime;
class Checks {static int Main(){int failures=0;Action<string,bool> check=(name,ok)=>{Console.WriteLine((ok?"PASS ":"FAIL ")+name);if(!ok)failures++;};var material=new Material(Shader.Find("Standard"));var r=new Renderer{sharedMaterials=new[]{material},shadowCastingMode=ShadowCastingMode.ShadowsOnly,receiveShadows=false};MonoBehaviour.TestChildren=new[]{r};var toggle=new ShadowlessFighterMaterials();toggle.Apply();check("exact material identity while off",ReferenceEquals(material,r.sharedMaterials[0]));toggle.Apply();toggle.Restore();check("authored flags restore",r.shadowCastingMode==ShadowCastingMode.ShadowsOnly&&!r.receiveShadows);r.shadowCastingMode=ShadowCastingMode.TwoSided;r.receiveShadows=true;toggle.Restore();check("repeat restore preserves updates",r.shadowCastingMode==ShadowCastingMode.TwoSided&&r.receiveShadows);var replacement=new Material(Shader.Find("Standard"));toggle.Apply();r.sharedMaterials=new[]{replacement};var late=new Renderer{sharedMaterials=new[]{material},shadowCastingMode=ShadowCastingMode.TwoSided,receiveShadows=false};MonoBehaviour.TestChildren=new[]{r,late};toggle.Apply();toggle.Restore();check("runtime material updates survive",ReferenceEquals(replacement,r.sharedMaterials[0]));check("new child authored flags",late.shadowCastingMode==ShadowCastingMode.TwoSided&&!late.receiveShadows);return failures>0?1:0;}}
